-- Hozoryar: fresh installation only. Select a NEW EMPTY database in phpMyAdmin.
-- Generated by php php/cli/build-install-sql.php; no users, passwords or live data included.
-- Do not import this file together with the numbered migrations.
SET NAMES utf8mb4;
SET SESSION time_zone = '+03:30';

CREATE TABLE schema_migrations (
 name VARCHAR(120) PRIMARY KEY, checksum CHAR(64) NOT NULL,
 status VARCHAR(16) NOT NULL, applied_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- BEGIN 001_auth_foundation.sql
INSERT INTO schema_migrations(name,checksum,status) VALUES('001_auth_foundation.sql','8874a89029002d52f8d52a87de1e9836ef4e712b38aed5ff126f68b16bd17627','started');
-- Install into a new dedicated MySQL/MariaDB database; do not run on Khatyar.
CREATE TABLE companies (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  slug VARCHAR(60) NOT NULL UNIQUE,
  active TINYINT(1) NOT NULL DEFAULT 1,
  subscription_end DATE NULL,
  max_personnel INT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE users (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT UNSIGNED NOT NULL,
  name VARCHAR(160) NOT NULL,
  username VARCHAR(60) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role ENUM('owner','manager','employee') NOT NULL DEFAULT 'employee',
  active TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_company_username (company_id,username),
  UNIQUE KEY uq_company_user (company_id,id),
  CONSTRAINT fk_users_company FOREIGN KEY (company_id) REFERENCES companies(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sessions (
  token_hash CHAR(64) PRIMARY KEY,
  company_id BIGINT UNSIGNED NOT NULL,
  user_id BIGINT UNSIGNED NOT NULL,
  expires_at DATETIME NOT NULL,
  KEY idx_sessions_expiry (expires_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (company_id,user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE login_limits (
  login_key CHAR(64) PRIMARY KEY,
  failures SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  window_start DATETIME NOT NULL,
  blocked_until DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE schema_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE name='001_auth_foundation.sql';
-- END 001_auth_foundation.sql

-- BEGIN 002_personnel_attendance.sql
INSERT INTO schema_migrations(name,checksum,status) VALUES('002_personnel_attendance.sql','e183a0785665c56ce79a8e016abcf6849416891399540e53461f33e088d6eac1','started');
-- Apply only after 001_auth_foundation.sql to a dedicated Hozoryar database.
CREATE TABLE company_settings (
 company_id BIGINT UNSIGNED PRIMARY KEY,
 map_provider ENUM('osm','neshan') NOT NULL DEFAULT 'osm',
 neshan_api_key VARCHAR(200) NULL,
 sms_provider ENUM('disabled','kavenegar') NOT NULL DEFAULT 'disabled',
 sms_api_key VARCHAR(200) NULL,
 require_location TINYINT(1) NOT NULL DEFAULT 0,
 enforce_shift_window TINYINT(1) NOT NULL DEFAULT 0,
 geofence_lat DECIMAL(10,7) NULL,
 geofence_lng DECIMAL(10,7) NULL,
 geofence_radius_m INT NOT NULL DEFAULT 200,
 approval_steps TINYINT NOT NULL DEFAULT 1,
 annual_leave_minutes INT NOT NULL DEFAULT 12480,
 features_json TEXT NOT NULL,
 FOREIGN KEY(company_id) REFERENCES companies(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE zones (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 name VARCHAR(100) NOT NULL,
 requires_substitute TINYINT(1) NOT NULL DEFAULT 0,
 UNIQUE KEY uq_zone_name(company_id,name),
 UNIQUE KEY uq_zone_company_id(company_id,id),
 FOREIGN KEY(company_id) REFERENCES companies(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE users ADD COLUMN zone_id BIGINT UNSIGNED NULL,
 ADD COLUMN can_be_substitute TINYINT(1) NOT NULL DEFAULT 0,
 ADD CONSTRAINT fk_user_zone FOREIGN KEY(company_id,zone_id) REFERENCES zones(company_id,id);

CREATE TABLE shifts (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 name VARCHAR(120) NOT NULL,
 start_time CHAR(5) NOT NULL,
 end_time CHAR(5) NOT NULL,
 duty_minutes SMALLINT UNSIGNED NOT NULL,
 daily_ot_cap SMALLINT UNSIGNED NOT NULL DEFAULT 27,
 schedule_kind ENUM('fixed','weekly','rotating','rotation_segments','floating','advanced','auto') NOT NULL DEFAULT 'fixed',
 schedule_json TEXT NOT NULL,
 UNIQUE KEY uq_shift_company_id(company_id,id),
 FOREIGN KEY(company_id) REFERENCES companies(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE assignments (
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 shift_id BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(company_id,user_id),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,shift_id) REFERENCES shifts(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE attendance (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 checked_in_at VARCHAR(24) NOT NULL,
 checked_out_at VARCHAR(24) NULL,
 lat DECIMAL(10,7) NULL,
 lng DECIMAL(10,7) NULL,
 accuracy DECIMAL(10,2) NULL,
 KEY ix_attendance_user(company_id,user_id,checked_in_at),
 UNIQUE KEY uq_attendance_company_id(company_id,id),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE attendance_events (
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 event_id VARCHAR(64) NOT NULL,
 action ENUM('in','out') NOT NULL,
 attendance_id BIGINT UNSIGNED NOT NULL,
 recorded_at VARCHAR(24) NOT NULL,
 PRIMARY KEY(company_id,user_id,event_id),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,attendance_id) REFERENCES attendance(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE audit_logs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 actor_user_id BIGINT UNSIGNED NOT NULL,
 action VARCHAR(80) NOT NULL,
 target_type VARCHAR(80) NOT NULL,
 target_id BIGINT UNSIGNED NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY ix_audit_company(company_id,created_at),
 FOREIGN KEY(company_id,actor_user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE schema_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE name='002_personnel_attendance.sql';
-- END 002_personnel_attendance.sql

-- BEGIN 003_requests.sql
INSERT INTO schema_migrations(name,checksum,status) VALUES('003_requests.sql','cfdde4c83269ed831942cf5deb17ca2e85b137960193492eb0ae4fbc29e19e36','started');
-- Install after 002_personnel_attendance.sql in the dedicated Hozoryar database.
CREATE TABLE personnel_requests (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 type ENUM('annual_leave','sick_leave','unpaid_leave','mission') NOT NULL,
 work_date DATE NOT NULL,
 end_date DATE NOT NULL,
 unit ENUM('hourly','daily') NOT NULL DEFAULT 'hourly',
 minutes SMALLINT UNSIGNED NOT NULL,
 description VARCHAR(500) NOT NULL DEFAULT '',
 status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
 substitute_user_id BIGINT UNSIGNED NULL,
 decided_by BIGINT UNSIGNED NULL,
 decided_at VARCHAR(24) NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_request_company_id(company_id,id),
 KEY idx_requests_substitute(company_id,substitute_user_id,status,work_date,end_date),
 KEY idx_requests_user(company_id,user_id,type,status,work_date,end_date),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,substitute_user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,decided_by) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE request_decisions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 request_id BIGINT UNSIGNED NOT NULL,
 stage TINYINT UNSIGNED NOT NULL,
 actor_user_id BIGINT UNSIGNED NOT NULL,
 outcome ENUM('approved','rejected') NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_request_stage(company_id,request_id,stage),
 FOREIGN KEY(company_id,request_id) REFERENCES personnel_requests(company_id,id),
 FOREIGN KEY(company_id,actor_user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE substitute_assignments (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 request_id BIGINT UNSIGNED NOT NULL,
 substitute_user_id BIGINT UNSIGNED NOT NULL,
 absent_user_id BIGINT UNSIGNED NOT NULL,
 from_date DATE NOT NULL,
 to_date DATE NOT NULL,
 UNIQUE KEY uq_assignment_request(company_id,request_id),
 KEY idx_substitute_period(company_id,substitute_user_id,from_date,to_date),
 FOREIGN KEY(company_id,request_id) REFERENCES personnel_requests(company_id,id),
 FOREIGN KEY(company_id,substitute_user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,absent_user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE schema_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE name='003_requests.sql';
-- END 003_requests.sql

