-- BEGIN 005_monitoring.sql
INSERT INTO schema_migrations(name,checksum,status) VALUES('005_monitoring.sql','30dac468ce69ae23915625c191c8b331ed0259993cf12637c4a5ba7a828b32ae','started');
-- Company-scoped monitoring data. Retention: 30 days for location_history.
CREATE TABLE locations (
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 lat DECIMAL(10,7) NOT NULL,
 lng DECIMAL(10,7) NOT NULL,
 accuracy DECIMAL(10,2) NULL,
 recorded_at VARCHAR(24) NOT NULL,
 PRIMARY KEY(company_id,user_id),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE location_history (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 lat DECIMAL(10,7) NOT NULL,
 lng DECIMAL(10,7) NOT NULL,
 accuracy DECIMAL(10,2) NULL,
 recorded_at VARCHAR(24) NOT NULL,
 KEY idx_location_recent(company_id,user_id,recorded_at),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monitoring_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 company_id BIGINT UNSIGNED NOT NULL,
 user_id BIGINT UNSIGNED NOT NULL,
 attendance_id BIGINT UNSIGNED NOT NULL,
 kind ENUM('gps_off','gps_on','internet_off','internet_on') NOT NULL,
 recorded_at VARCHAR(24) NOT NULL,
 KEY idx_monitor_user(company_id,user_id,recorded_at),
 FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,attendance_id) REFERENCES attendance(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE schema_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE name='005_monitoring.sql';
-- END 005_monitoring.sql

-- BEGIN 006_work_archives.sql
INSERT INTO schema_migrations(name,checksum,status) VALUES('006_work_archives.sql','16c2995cd6f5960d9c39bbba6dcc4452169db46231bb6fca348ff83ca8592b17','started');
-- Requires 001..005; financial confirmation is minutes-only and not legal payroll.
CREATE TABLE work_month_archives (
 company_id BIGINT UNSIGNED NOT NULL,
 month VARCHAR(9) NOT NULL,
 snapshot_json LONGTEXT NOT NULL,
 created_by BIGINT UNSIGNED NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(company_id,month),
 FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE work_month_reviews (
 company_id BIGINT UNSIGNED NOT NULL,
 month VARCHAR(9) NOT NULL,
 status ENUM('pending_review','reviewed','approved') NOT NULL DEFAULT 'pending_review',
 reviewer_user_id BIGINT UNSIGNED NULL,
 reviewed_at VARCHAR(24) NULL,
 approver_user_id BIGINT UNSIGNED NULL,
 approved_at VARCHAR(24) NULL,
 PRIMARY KEY(company_id,month),
 FOREIGN KEY(company_id,month) REFERENCES work_month_archives(company_id,month),
 FOREIGN KEY(company_id,reviewer_user_id) REFERENCES users(company_id,id),
 FOREIGN KEY(company_id,approver_user_id) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE work_month_finance (
 company_id BIGINT UNSIGNED NOT NULL,
 month VARCHAR(9) NOT NULL,
 snapshot_sha256 CHAR(64) NOT NULL,
 include_surplus TINYINT(1) NOT NULL DEFAULT 0,
 payroll_json LONGTEXT NOT NULL,
 confirmed_by BIGINT UNSIGNED NOT NULL,
 confirmed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(company_id,month),
 FOREIGN KEY(company_id,month) REFERENCES work_month_archives(company_id,month),
 FOREIGN KEY(company_id,confirmed_by) REFERENCES users(company_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE schema_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE name='006_work_archives.sql';
-- END 006_work_archives.sql

